import { createRoute, z } from '@hono/zod-openapi'

const ACHClassSchema = z
  .enum(['ccd', 'ppd', 'tel', 'web'])
  .openapi({
    description:
      'Specifies the use case of the transfer. Required for transfers on an ACH network.\n\n`"ccd"` - Corporate Credit or Debit - fund transfer between two corporate bank accounts\n\n`"ppd"` - Prearranged Payment or Deposit - the transfer is part of a pre-existing relationship with a consumer, eg. bill payment\n\n`"tel"` - Telephone-Initiated Entry\n\n`"web"` - Internet-Initiated Entry - debits from a consumer’s account where their authorization is obtained over the Internet',
    title: 'ACHClass',
  })
  .openapi('ACHClass')

const APIClientIDSchema = z
  .string()
  .openapi({
    description:
      'Your Plaid API `client_id`. The `client_id` is required and may be provided either in the `PLAID-CLIENT-ID` header or as part of a request body.',
    title: 'ClientID',
  })
  .openapi('APIClientID')

const APISecretSchema = z
  .string()
  .openapi({
    description:
      'Your Plaid API `secret`. The `secret` is required and may be provided either in the `PLAID-SECRET` header or as part of a request body.',
    title: 'APISecret',
  })
  .openapi('APISecret')

const APRSchema = z
  .looseObject({
    apr_percentage: z.float64().openapi({ description: 'Annual Percentage Rate applied.\n' }),
    apr_type: z
      .enum(['balance_transfer_apr', 'cash_apr', 'purchase_apr', 'special'])
      .openapi({ description: 'The type of balance to which the APR applies.' }),
    balance_subject_to_apr: z
      .float64()
      .nullable()
      .openapi({
        description:
          'Amount of money that is subjected to the APR if a balance was carried beyond payment due date. How it is calculated can vary by card issuer. It is often calculated as an average daily balance.',
      }),
    interest_charge_amount: z
      .float64()
      .nullable()
      .openapi({ description: 'Amount of money charged due to interest from last statement.' }),
  })
  .openapi({
    description: 'Information about the APR on the account.',
    required: ['apr_percentage', 'apr_type', 'balance_subject_to_apr', 'interest_charge_amount'],
    title: 'APR',
  })
  .openapi('APR')

const AccessTokenSchema = z
  .string()
  .openapi({
    description: 'The access token associated with the Item data is being requested for.',
    title: 'AccessToken',
  })
  .openapi('AccessToken')

const AccessTokenNullableSchema = z
  .string()
  .nullable()
  .openapi({
    description: 'The access token associated with the Item data is being requested for.',
  })
  .openapi('AccessTokenNullable')

const AccountProductAccessSchema = z
  .object({
    account_data: z
      .boolean()
      .nullable()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'Allow the application to access account data. Only used by certain partners. If relevant to the partner and unset, defaults to `true`.',
      }),
    statements: z
      .boolean()
      .nullable()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'Allow the application to access bank statements. Only used by certain partners. If relevant to the partner and unset, defaults to `true`.',
      }),
    tax_documents: z
      .boolean()
      .nullable()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'Allow the application to access tax documents. Only used by certain partners. If relevant to the partner and unset, defaults to `true`.',
      }),
  })
  .openapi({
    description: 'Allow the application to access specific products on this account',
    required: [],
  })
  .openapi('AccountProductAccess')

const AccountProductAccessNullableSchema = AccountProductAccessSchema.and(z.looseObject({}))
  .nullable()
  .openapi({ description: 'Allow the application to access specific products on this account' })
  .openapi('AccountProductAccessNullable')

const AccountAccessSchema = z
  .object({
    account_product_access: AccountProductAccessNullableSchema.exactOptional(),
    authorized: z
      .boolean()
      .nullable()
      .default(true)
      .exactOptional()
      .openapi({
        description:
          'Allow the application to see this account (and associated details, including balance) in the list of accounts  If unset, defaults to `true`.',
      }),
    unique_id: z
      .string()
      .openapi({
        description:
          'The unique account identifier for this account. This value must match that returned by the data access API for this account.',
      }),
  })
  .openapi({
    description:
      'Allow or disallow product access by account. Unlisted (e.g. missing) accounts will be considered `new_accounts`.',
    required: ['unique_id'],
  })
  .openapi('AccountAccess')

const AccountBalanceSchema = z
  .looseObject({
    available: z
      .float64()
      .nullable()
      .openapi({
        description:
          'The amount of funds available to be withdrawn from the account, as determined by the financial institution.\n\nFor `credit`-type accounts, the `available` balance typically equals the `limit` less the `current` balance, less any pending outflows plus any pending inflows.\n\nFor `depository`-type accounts, the `available` balance typically equals the `current` balance less any pending outflows plus any pending inflows. For `depository`-type accounts, the `available` balance does not include the overdraft limit.\n\nFor `investment`-type accounts (or `brokerage`-type accounts for API versions 2018-05-22 and earlier), the `available` balance is the total cash available to withdraw as presented by the institution.\n\nNote that not all institutions calculate the `available`  balance. In the event that `available` balance is unavailable, Plaid will return an `available` balance value of `null`.\n\nAvailable balance may be cached and is not guaranteed to be up-to-date in realtime unless the value was returned by `/accounts/balance/get`.\n\nIf `current` is `null` this field is guaranteed not to be `null`.',
      }),
    current: z
      .float64()
      .nullable()
      .openapi({
        description:
          "The total amount of funds in or owed by the account.\n\nFor `credit`-type accounts, a positive balance indicates the amount owed; a negative amount indicates the lender owing the account holder.\n\nFor `loan`-type accounts, the current balance is the principal remaining on the loan, except in the case of student loan accounts at Sallie Mae (`ins_116944`). For Sallie Mae student loans, the account's balance includes both principal and any outstanding interest.\n\nFor `investment`-type accounts (or `brokerage`-type accounts for API versions 2018-05-22 and earlier), the current balance is the total value of assets as presented by the institution.\n\nNote that balance information may be cached unless the value was returned by `/accounts/balance/get`; if the Item is enabled for Transactions, the balance will be at least as recent as the most recent Transaction update. If you require realtime balance information, use the `available` balance as provided by `/accounts/balance/get`.\n\nWhen returned by `/accounts/balance/get`, this field may be `null`. When this happens, `available` is guaranteed not to be `null`.",
      }),
    iso_currency_code: z
      .string()
      .nullable()
      .openapi({
        description:
          'The ISO-4217 currency code of the balance. Always null if `unofficial_currency_code` is non-null.',
      }),
    last_updated_datetime: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Timestamp in [ISO 8601](https://wikipedia.org/wiki/ISO_8601) format (`YYYY-MM-DDTHH:mm:ssZ`) indicating the last time that the balance for the given account has been updated\n\nThis is currently only provided when the `min_last_updated_datetime` is passed when calling `/accounts/balance/get` for `ins_128026` (Capital One).',
      }),
    limit: z
      .float64()
      .nullable()
      .openapi({
        description:
          'For `credit`-type accounts, this represents the credit limit.\n\nFor `depository`-type accounts, this represents the pre-arranged overdraft limit, which is common for current (checking) accounts in Europe.\n\nIn North America, this field is typically only available for `credit`-type accounts.',
      }),
    unofficial_currency_code: z
      .string()
      .nullable()
      .openapi({
        description:
          'The unofficial currency code associated with the balance. Always null if `iso_currency_code` is non-null. Unofficial currency codes are used for currencies that do not have official ISO currency codes, such as cryptocurrencies and the currencies of certain countries.\n\nSee the [currency code schema](https://plaid.com/docs/api/accounts#currency-code-schema) for a full listing of supported `unofficial_currency_code`s.',
      }),
  })
  .openapi({
    description:
      'A set of fields describing the balance for an account. Balance information may be cached unless the balance object was returned by `/accounts/balance/get`.',
    required: ['available', 'current', 'limit', 'iso_currency_code', 'unofficial_currency_code'],
    title: 'AccountBalance',
  })
  .openapi('AccountBalance')

