const PaymentSchemeSchema = z
  .union([
    z.literal(null),
    z.literal('LOCAL_DEFAULT'),
    z.literal('LOCAL_INSTANT'),
    z.literal('SEPA_CREDIT_TRANSFER'),
    z.literal('SEPA_CREDIT_TRANSFER_INSTANT'),
  ])
  .nullable()
  .openapi({
    description:
      'Payment scheme. If not specified - the default in the region will be used (e.g. `SEPA_CREDIT_TRANSFER` for EU). Using unsupported values will result in a failed payment.\n\n`LOCAL_DEFAULT`: The default payment scheme for the selected market and currency will be used.\n\n`LOCAL_INSTANT`: The instant payment scheme for the selected market and currency will be used (if applicable). Fees may be applied by the institution. If the market does not support an Instant Scheme (e.g. Denmark), the default in the region will be used.\n\n`SEPA_CREDIT_TRANSFER`: The standard payment to a beneficiary within the SEPA area.\n\n`SEPA_CREDIT_TRANSFER_INSTANT`: Instant payment within the SEPA area. May involve additional fees and may not be available at some banks.',
  })
  .openapi('PaymentScheme')

