const SecuritySchema = z
  .looseObject({
    close_price: z
      .float64()
      .nullable()
      .openapi({
        description:
          'Price of the security at the close of the previous trading session. Null for non-public securities.\n\nIf the security is a foreign currency this field will be updated daily and will be priced in USD.\n\nIf the security is a cryptocurrency, this field will be updated multiple times a day. As crypto prices can fluctuate quickly and data may become stale sooner than other asset classes, refer to `update_datetime` with the time when the price was last updated.\n',
      }),
    close_price_as_of: z.iso
      .date()
      .nullable()
      .openapi({
        description:
          'Date for which `close_price` is accurate. Always `null` if `close_price` is `null`.',
      }),
    cusip: z
      .string()
      .nullable()
      .openapi({
        description:
          "9-character CUSIP, an identifier assigned to North American securities. Please note that Plaid's customers must hold a license directly from CUSIP Global Services to receive CUSIP & ISIN data. This field will be null by default for new customers. For existing customers, this field will be null by default starting on Sept 15, 2023. If you would like access to this field, please contact your Plaid Account Manager or reach out to investments-vendors@plaid.com.",
      }),
    institution_id: z
      .string()
      .nullable()
      .openapi({
        description:
          'If `institution_security_id` is present, this field indicates the Plaid `institution_id` of the institution to whom the identifier belongs.',
      }),
    institution_security_id: z
      .string()
      .nullable()
      .openapi({ description: 'An identifier given to the security by the institution' }),
    is_cash_equivalent: z
      .boolean()
      .nullable()
      .openapi({
        description:
          'Indicates that a security is a highly liquid asset and can be treated like cash.',
      }),
    isin: z
      .string()
      .nullable()
      .openapi({
        description:
          "12-character ISIN, a globally unique securities identifier. Please note that Plaid's customers must hold a license directly from CUSIP Global Services to receive CUSIP & ISIN data. This field will be null by default for new customers. For existing customers, this field will be null by default starting on Sept 15, 2023. If you would like access to this field, please contact your Plaid Account Manager or reach out to investments-vendors@plaid.com.",
      }),
    iso_currency_code: z
      .string()
      .nullable()
      .openapi({
        description:
          'The ISO-4217 currency code of the price given. Always `null` if `unofficial_currency_code` is non-`null`.',
      }),
    name: z
      .string()
      .nullable()
      .openapi({ description: 'A descriptive name for the security, suitable for display.' }),
    proxy_security_id: z
      .string()
      .nullable()
      .openapi({
        description:
          'In certain cases, Plaid will provide the ID of another security whose performance resembles this security, typically when the original security has low volume, or when a private security can be modeled with a publicly traded security.',
      }),
    security_id: z
      .string()
      .openapi({
        description:
          'A unique, Plaid-specific identifier for the security, used to associate securities with holdings. Like all Plaid identifiers, the `security_id` is case sensitive. The `security_id` may change if inherent details of the security change due to a corporate action, for example, in the event of a ticker symbol change or CUSIP change.',
      }),
    sedol: z
      .string()
      .nullable()
      .openapi({
        description: '7-character SEDOL, an identifier assigned to securities in the UK.',
      }),
    ticker_symbol: z
      .string()
      .nullable()
      .openapi({
        description:
          'The security’s trading symbol for publicly traded securities, and otherwise a short identifier if available.',
      }),
    type: z
      .string()
      .nullable()
      .openapi({
        description:
          'The security type of the holding. Valid security types are:\n\n`cash`: Cash, currency, and money market funds\n\n`cryptocurrency`: Digital or virtual currencies\n\n`derivative`: Options, warrants, and other derivative instruments\n\n`equity`: Domestic and foreign equities\n\n`etf`: Multi-asset exchange-traded investment funds\n\n`fixed income`: Bonds and certificates of deposit (CDs)\n\n`loan`: Loans and loan receivables\n\n`mutual fund`: Open- and closed-end vehicles pooling funds of multiple investors\n\n`other`: Unknown or other investment types',
      }),
    unofficial_currency_code: z
      .string()
      .nullable()
      .openapi({
        description:
          'The unofficial currency code associated with the security. Always `null` if `iso_currency_code` is non-`null`. Unofficial currency codes are used for currencies that do not have official ISO currency codes, such as cryptocurrencies and the currencies of certain countries.\n\nSee the [currency code schema](https://plaid.com/docs/api/accounts#currency-code-schema) for a full listing of supported `iso_currency_code`s.',
      }),
    update_datetime: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Date and time at which `close_price` is accurate, in ISO 8601 format (YYYY-MM-DDTHH:mm:ssZ). Always `null` if `close_price` is `null`.',
      }),
  })
  .openapi({
    description: 'Contains details about a security',
    required: [
      'cusip',
      'sedol',
      'isin',
      'institution_security_id',
      'institution_id',
      'proxy_security_id',
      'name',
      'ticker_symbol',
      'is_cash_equivalent',
      'close_price',
      'close_price_as_of',
      'iso_currency_code',
      'unofficial_currency_code',
      'security_id',
      'type',
    ],
    title: 'Security',
  })
  .openapi('Security')

