const PaymentInitiationConsentCreateRequestSchema = z
  .object({
    client_id: APIClientIDSchema.exactOptional(),
    constraints: PaymentInitiationConsentConstraintsSchema,
    options: ExternalPaymentInitiationConsentOptionsSchema.exactOptional(),
    recipient_id: z
      .string()
      .openapi({
        description:
          'The ID of the recipient the payment consent is for. The created consent can be used to transfer funds to this recipient only.',
      }),
    reference: z
      .string()
      .min(1)
      .max(18)
      .openapi({
        description:
          'A reference for the payment consent. This must be an alphanumeric string with at most 18 characters and must not contain any special characters.',
      }),
    scopes: z
      .array(PaymentInitiationConsentScopeSchema)
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .openapi({ description: 'An array of payment consent scopes.' }),
    secret: APISecretSchema.exactOptional(),
  })
  .openapi({
    description:
      'PaymentInitiationConsentCreateRequest defines the request schema for `/payment_initiation/consent/create`',
    required: ['recipient_id', 'reference', 'scopes', 'constraints'],
  })
  .openapi('PaymentInitiationConsentCreateRequest')

