const SignalDecisionOutcomeSchema = z
  .enum(['APPROVE', 'REVIEW', 'REJECT', 'TAKE_OTHER_RISK_MEASURES', 'NOT_EVALUATED'])
  .nullable()
  .openapi({
    description:
      'The payment decision from the risk assessment.\n\n`APPROVE`: approve the transaction without requiring further actions from your customers. For example, use this field if you are placing a standard hold for all the approved transactions before making funds available to your customers. You should also use this field if you decide to accelerate the fund availability for your customers.\n\n`REVIEW`: the transaction requires manual review\n\n`REJECT`: reject the transaction\n\n`TAKE_OTHER_RISK_MEASURES`: for example, placing a longer hold on funds than those approved transactions or introducing customer frictions such as step-up verification/authentication\n\n`NOT_EVALUATED`: if only logging the Signal results without using them\n\nPossible values:  `APPROVE`, `REVIEW`, `REJECT`, `TAKE_OTHER_RISK_MEASURES`, `NOT_EVALUATED`\n',
  })
  .openapi('SignalDecisionOutcome')

const SignalPaymentMethodSchema = z
  .enum([
    'SAME_DAY_ACH',
    'NEXT_DAY_ACH',
    'STANDARD_ACH',
    'REAL_TIME_PAYMENTS',
    'DEBIT_CARD',
    'MULTIPLE_PAYMENT_METHODS',
  ])
  .nullable()
  .openapi({
    description:
      'The payment method to complete the transaction after the risk assessment. It may be different from the default payment method.\n\n`SAME_DAY_ACH`: Same Day ACH by NACHA. The debit transaction is processed and settled on the same day\n\n`NEXT_DAY_ACH`: Next Day ACH settlement for debit transactions, offered by some payment processors\n\n`STANDARD_ACH`: standard ACH by NACHA\n\n`REAL_TIME_PAYMENTS`: real-time payments such as RTP and FedNow\n\n`DEBIT_CARD`: if the default payment is over debit card networks\n\n`MULTIPLE_PAYMENT_METHODS`: if there is no default debit rail or there are multiple payment methods\n\nPossible values: `SAME_DAY_ACH`, `NEXT_DAY_ACH`, `STANDARD_ACH`, `REAL_TIME_PAYMENTS`, `DEBIT_CARD`, `MULTIPLE_PAYMENT_METHODS`\n',
  })
  .openapi('SignalPaymentMethod')

const ProcessorSignalDecisionReportRequestSchema = z
  .object({
    amount_instantly_available: z
      .float64()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The amount (in USD) made available to your customers instantly following the debit transaction. It could be a partial amount of the requested transaction (example: 102.05).',
      }),
    client_id: APIClientIDSchema.exactOptional(),
    client_transaction_id: z
      .string()
      .min(1)
      .max(36)
      .openapi({
        description:
          'Must be the same as the `client_transaction_id` supplied when calling `/signal/evaluate`',
      }),
    days_funds_on_hold: z
      .int()
      .min(0)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The actual number of days (hold time) since the ACH debit transaction that you wait before making funds available to your customers. The holding time could affect the ACH return rate.\n\nFor example, use 0 if you make funds available to your customers instantly or the same day following the debit transaction, or 1 if you make funds available the next day following the debit initialization.',
      }),
    decision_outcome: SignalDecisionOutcomeSchema.exactOptional(),
    initiated: z
      .boolean()
      .openapi({
        description:
          '`true` if the ACH transaction was initiated, `false` otherwise.\n\nThis field must be returned as a boolean. If formatted incorrectly, this will result in an [`INVALID_FIELD`](/docs/errors/invalid-request/#invalid_field) error.',
      }),
    payment_method: SignalPaymentMethodSchema.exactOptional(),
    processor_token: ProcessorTokenSchema,
    secret: APISecretSchema.exactOptional(),
  })
  .openapi({
    description:
      'ProcessorSignalDecisionReportRequest defines the request schema for `/processor/signal/decision/report`',
    required: ['processor_token', 'client_transaction_id', 'initiated'],
    title: 'ProcessorSignalDecisionReportRequest',
  })
  .openapi('ProcessorSignalDecisionReportRequest')

const ProcessorSignalDecisionReportResponseSchema = z
  .looseObject({ request_id: RequestIDSchema })
  .openapi({
    description:
      'ProcessorSignalDecisionReportResponse defines the response schema for `/processor/signal/decision/report`',
    required: ['request_id'],
    title: 'ProcessorSignalDecisionReportResponse',
  })
  .openapi('ProcessorSignalDecisionReportResponse')

const SignalDeviceSchema = z
  .object({
    ip_address: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'The IP address of the device that initiated the transaction' }),
    user_agent: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The user agent of the device that initiated the transaction (e.g. "Mozilla/5.0")',
      }),
  })
  .openapi({
    description: "Details about the end user's device",
    title: 'SignalEvaluateDevice',
    required: [],
  })
  .openapi('SignalDevice')

const SignalPersonNameSchema = z
  .object({
    family_name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: "The user's family name / surname" }),
    given_name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "The user's given name. If the user has a one-word name, it should be provided in this field.",
      }),
    middle_name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: "The user's middle name" }),
    prefix: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'The user\'s name prefix (e.g. "Mr.")' }),
    suffix: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'The user\'s name suffix (e.g. "II")' }),
  })
  .nullable()
  .openapi({ description: "The user's legal name", title: 'SignalPersonName', required: [] })
  .openapi('SignalPersonName')

const SignalUserSchema = z
  .object({
    address: SignalAddressDataSchema.exactOptional(),
    email_address: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: "The user's email address." }),
    name: SignalPersonNameSchema.exactOptional(),
    phone_number: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The user\'s phone number, in E.164 format: +{countrycode}{number}. For example: "+14151234567"',
      }),
  })
  .openapi({
    description:
      'Details about the end user initiating the transaction (i.e., the account holder).',
    title: 'SignalUser',
    required: [],
  })
  .openapi('SignalUser')

const ProcessorSignalEvaluateRequestSchema = z
  .object({
    amount: z.float64().openapi({ description: 'The transaction amount, in USD (e.g. `102.05`)' }),
    client_id: APIClientIDSchema.exactOptional(),
    client_transaction_id: z
      .string()
      .min(1)
      .max(36)
      .openapi({
        description:
          'The unique ID that you would like to use to refer to this transaction. For your convenience mapping your internal data, you could use your internal ID/identifier for this transaction. The max length for this field is 36 characters.',
      }),
    client_user_id: z
      .string()
      .max(36)
      .exactOptional()
      .openapi({
        description:
          'A unique ID that identifies the end user in your system. This ID is used to correlate requests by a user with multiple Items. The max length for this field is 36 characters. Personally identifiable information, such as an email address or phone number, should not be used in the `client_user_id`.',
      }),
    default_payment_method: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The default ACH or non-ACH payment method to complete the transaction.\n`SAME_DAY_ACH`: Same Day ACH by NACHA. The debit transaction is processed and settled on the same day\n`NEXT_DAY_ACH`: Next Day ACH settlement for debit transactions, offered by some payment processors\n`STANDARD_ACH`: standard ACH by NACHA\n`REAL_TIME_PAYMENTS`: real-time payments such as RTP and FedNow\n`DEBIT_CARD`: if the default payment is over debit card networks\n`MULTIPLE_PAYMENT_METHODS`: if there is no default debit rail or there are multiple payment methods\nPossible values:  `SAME_DAY_ACH`, `NEXT_DAY_ACH`, `STANDARD_ACH`, `REAL_TIME_PAYMENTS`, `DEBIT_CARD`, `MULTIPLE_PAYMENT_METHODS`',
      }),
    device: SignalDeviceSchema.exactOptional(),
    is_recurring: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          '**true** if the ACH transaction is a recurring transaction; **false** otherwise ',
      }),
    processor_token: ProcessorTokenSchema,
    secret: APISecretSchema.exactOptional(),
    user: SignalUserSchema.exactOptional(),
    user_present: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          '`true` if the end user is present while initiating the ACH transfer and the endpoint is being called; `false` otherwise (for example, when the ACH transfer is scheduled and the end user is not present, or you call this endpoint after the ACH transfer but before submitting the Nacha file for ACH processing).',
      }),
  })
  .openapi({
    description:
      'ProcessorSignalEvaluateRequest defines the request schema for `/processor/signal/evaluate`',
    required: ['processor_token', 'client_transaction_id', 'amount'],
    title: 'ProcessorSignalEvaluateRequest',
  })
  .openapi('ProcessorSignalEvaluateRequest')

