const TransferAuthorizationDecisionSchema = z
  .enum(['approved', 'declined'])
  .openapi({
    description:
      "\nA decision regarding the proposed transfer.\n\n`approved` – The proposed transfer has received the end user's consent and has been approved for processing by Plaid. The `decision_rationale` field is set if Plaid was unable to fetch the account information. You may proceed with the transfer, but further review is recommended (i.e., use Link in update to re-authenticate your user when `decision_rationale.code` is `ITEM_LOGIN_REQUIRED`). Refer to the `code` field in the `decision_rationale` object for details.\n\n`declined` – Plaid reviewed the proposed transfer and declined processing. Refer to the `code` field in the `decision_rationale` object for details.",
  })
  .openapi('TransferAuthorizationDecision')

const TransferAuthorizationDecisionRationaleCodeSchema = z
  .enum([
    'NSF',
    'RISK',
    'TRANSFER_LIMIT_REACHED',
    'MANUALLY_VERIFIED_ITEM',
    'ITEM_LOGIN_REQUIRED',
    'PAYMENT_PROFILE_LOGIN_REQUIRED',
    'ERROR',
    'MIGRATED_ACCOUNT_ITEM',
  ])
  .openapi({
    description:
      'A code representing the rationale for approving or declining the proposed transfer. Possible values are:\n\n`MANUALLY_VERIFIED_ITEM` – Item created via same-day micro deposits, limited information available. Plaid will offer `approved` as a transaction decision.\n\n`ITEM_LOGIN_REQUIRED` – Unable to collect the account information due to Item staleness. Can be rectified using Link in update mode. Plaid will offer `approved` as a transaction decision.\n\n`PAYMENT_PROFILE_LOGIN_REQUIRED` - Unable to collect the account information due to invalid login when using Payment Profiles. Can be rectified using update mode for Payment Profile. Plaid will offer `approved` as a transaction decision.\n\n`ERROR` – Unable to collect the account information due to an error. Plaid will offer `approved` as a transaction decision.\n\n`NSF` – Transaction likely to result in a return due to insufficient funds. Plaid will offer `declined` as a transaction decision.\n\n`RISK` - Transaction is high-risk. Plaid will offer `declined` as a transaction decision.\n\n`TRANSFER_LIMIT_REACHED` - One or several transfer limits are reached, e.g. monthly transfer limit. Plaid will offer `declined` as a transaction decision.\n\n`MIGRATED_ACCOUNT_ITEM` - Item created via `/transfer/account_migration` endpoint, limited information available. Plaid will offer `approved` as a transaction decision.',
  })
  .openapi('TransferAuthorizationDecisionRationaleCode')

