const SyncUpdatesAvailableWebhookSchema = z
  .looseObject({
    environment: WebhookEnvironmentValuesSchema,
    historical_update_complete: z
      .boolean()
      .openapi({ description: 'Indicates if historical pull information is available.' }),
    initial_update_complete: z
      .boolean()
      .openapi({ description: 'Indicates if initial pull information is available.' }),
    item_id: ItemIdSchema,
    webhook_code: z.string().openapi({ description: '`SYNC_UPDATES_AVAILABLE`' }),
    webhook_type: z.string().openapi({ description: '`TRANSACTIONS`' }),
  })
  .openapi({
    description:
      "Fired when an Item's transactions change. This can be due to any event resulting in new changes, such as an initial 30-day transactions fetch upon the initialization of an Item with transactions, the backfill of historical transactions that occurs shortly after, or when changes are populated from a regularly-scheduled transactions update job. It is recommended to listen for the `SYNC_UPDATES_AVAILABLE` webhook when using the `/transactions/sync` endpoint. Note that when using `/transactions/sync` the older webhooks `INITIAL_UPDATE`, `HISTORICAL_UPDATE`, `DEFAULT_UPDATE`, and `TRANSACTIONS_REMOVED`, which are intended for use with `/transactions/get`, will also continue to be sent in order to maintain backwards compatibility. It is not necessary to listen for and respond to those webhooks when using `/transactions/sync`.\n\nAfter receipt of this webhook, the new changes can be fetched for the Item from `/transactions/sync`.\n\nNote that to receive this webhook for an Item, `/transactions/sync` must have been called at least once on that Item. This means that, unlike the `INITIAL_UPDATE` and `HISTORICAL_UPDATE` webhooks, it will not fire immediately upon Item creation. If `/transactions/sync` is called on an Item that was *not* initialized with Transactions, the webhook will fire twice: once the first 30 days of transactions data has been fetched, and a second time when all available historical transactions data has been fetched.\n\nThis webhook will typically not fire in the Sandbox environment, due to the lack of dynamic transactions data. To test this webhook in Sandbox, call `/sandbox/item/fire_webhook`.",
    required: [
      'webhook_type',
      'webhook_code',
      'item_id',
      'initial_update_complete',
      'historical_update_complete',
      'environment',
    ],
    title: 'SyncUpdatesAvailableWebhook',
    'x-examples': {
      'example-1': {
        environment: 'production',
        historical_update_complete: false,
        initial_update_complete: true,
        item_id: 'wz666MBjYWTp2PDzzggYhM6oWWmBb',
        webhook_code: 'SYNC_UPDATES_AVAILABLE',
        webhook_type: 'TRANSACTIONS',
      },
    },
  })
  .openapi('SyncUpdatesAvailableWebhook')

