const TransactionStreamStatusSchema = z
  .enum(['UNKNOWN', 'MATURE', 'EARLY_DETECTION', 'TOMBSTONED'])
  .openapi({
    description:
      'The current status of the transaction stream.\n\n`MATURE`: A `MATURE` recurring stream should have at least 3 transactions and happen on a regular cadence.\n\n`EARLY_DETECTION`: When a recurring transaction first appears in the transaction history and before it fulfills the requirement of a mature stream, the status will be `EARLY_DETECTION`.\n\n`TOMBSTONED`: A stream that was previously in the `EARLY_DETECTION` status will move to the `TOMBSTONED` status when no further transactions were found at the next expected date.\n\n`UNKNOWN`: A stream is assigned an `UNKNOWN` status when none of the other statuses are applicable.',
    title: 'TransactionStreamStatus',
  })
  .openapi('TransactionStreamStatus')

