const TransactionsSyncResponseSchema = z
  .looseObject({
    added: z
      .array(TransactionSchema)
      .openapi({
        description:
          'Transactions that have been added to the Item since `cursor` ordered by ascending last modified time.',
      }),
    has_more: z
      .boolean()
      .openapi({
        description:
          'Represents if more than requested count of transaction updates exist. If true, the additional updates can be fetched by making an additional request with `cursor` set to `next_cursor`. If `has_more` is true, it’s important to pull all available pages, to make it less likely for underlying data changes to conflict with pagination.',
      }),
    modified: z
      .array(TransactionSchema)
      .openapi({
        description:
          'Transactions that have been modified on the Item since `cursor` ordered by ascending last modified time.',
      }),
    next_cursor: z
      .string()
      .openapi({
        description:
          'Cursor used for fetching any future updates after the latest update provided in this response. The cursor obtained after all pages have been pulled (indicated by `has_more` being `false`) will be valid for at least 1 year. This cursor should be persisted for later calls. If transactions are not yet available, this will be an empty string.',
      }),
    removed: z
      .array(RemovedTransactionSchema)
      .openapi({
        description:
          'Transactions that have been removed from the Item since `cursor` ordered by ascending last modified time.',
      }),
    request_id: RequestIDSchema,
  })
  .openapi({
    description: 'TransactionsSyncResponse defines the response schema for `/transactions/sync`',
    required: ['added', 'modified', 'removed', 'next_cursor', 'has_more', 'request_id'],
  })
  .openapi('TransactionsSyncResponse')

const TransferAuthorizationGuaranteeDecisionSchema = z
  .union([z.literal('GUARANTEED'), z.literal('NOT_GUARANTEED'), z.literal(null)])
  .nullable()
  .openapi({
    description:
      'Indicates whether the transfer is guaranteed by Plaid (Guarantee customers only). This field will contain either `GUARANTEED` or `NOT_GUARANTEED` indicating whether Plaid will guarantee the transfer. If the transfer is not guaranteed, additional information will be provided in the `guarantee_decision_rationale` field. Refer to the `code` field in `guarantee_decision_rationale` for details.',
  })
  .openapi('TransferAuthorizationGuaranteeDecision')

const TransferAuthorizationGuaranteeDecisionRationaleCodeSchema = z
  .enum([
    'RETURN_BANK',
    'RETURN_CUSTOMER',
    'GUARANTEE_LIMIT_REACHED',
    'RISK_ESTIMATE_UNAVAILABLE',
    'REQUIRED_PARAM_MISSING',
  ])
  .openapi({
    description:
      'A code representing the reason Plaid declined to guarantee this transfer:\n\n`RETURN_BANK`: The risk of a bank-initiated return (for example, an R01/NSF) is too high to guarantee this transfer.\n\n`RETURN_CUSTOMER`: The risk of a customer-initiated return (for example, a R10/Unauthorized) is too high to guarantee this transfer.\n\n`GUARANTEE_LIMIT_REACHED`: This transfer is low-risk, but Guarantee has exhausted an internal limit on the number or rate of guarantees that applies to this transfer.\n\n`RISK_ESTIMATE_UNAVAILABLE`: A risk estimate is unavailable for this Item.\n\n`REQUIRED_PARAM_MISSING`: Required fields are missing.',
  })
  .openapi('TransferAuthorizationGuaranteeDecisionRationaleCode')

const TransferAuthorizationGuaranteeDecisionRationaleSchema = z
  .looseObject({
    code: TransferAuthorizationGuaranteeDecisionRationaleCodeSchema,
    description: z
      .string()
      .openapi({
        description: 'A human-readable description of why the transfer cannot be guaranteed.',
      }),
  })
  .nullable()
  .openapi({
    description:
      "The rationale for Plaid's decision to not guarantee a transfer. Will be `null` unless `guarantee_decision` is `NOT_GUARANTEED`.",
    required: ['code', 'description'],
    title: 'TransferAuthorizationGuaranteeDecisionRationale',
  })
  .openapi('TransferAuthorizationGuaranteeDecisionRationale')

