export const postItemAccessTokenInvalidateRoute = createRoute({
  method: 'post',
  path: '/item/access_token/invalidate',
  tags: ['plaid'],
  summary: 'Invalidate access_token',
  description:
    'By default, the `access_token` associated with an Item does not expire and should be stored in a persistent, secure manner.\n\nYou can use the `/item/access_token/invalidate` endpoint to rotate the `access_token` associated with an Item. The endpoint returns a new `access_token` and immediately invalidates the previous `access_token`.\n',
  externalDocs: { url: '/api/tokens/#itemaccess_tokeninvalidate' },
  operationId: 'itemAccessTokenInvalidate',
  request: {
    body: {
      content: { 'application/json': { schema: ItemAccessTokenInvalidateRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ItemAccessTokenInvalidateResponseSchema,
          examples: {
            'example-1': {
              value: {
                new_access_token: 'access-sandbox-8ab976e6-64bc-4b38-98f7-731e7a349970',
                request_id: 'm8MDnv9okwxFNBV',
              },
            },
          },
        },
      },
    },
  },
})

