export const postProcessorSignalEvaluateRoute = createRoute({
  method: 'post',
  path: '/processor/signal/evaluate',
  tags: ['plaid'],
  summary: 'Evaluate a planned ACH transaction',
  description:
    'Use `/processor/signal/evaluate` to evaluate a planned ACH transaction as a processor to get a return risk assessment (such as a risk score and risk tier) and additional risk signals.\n\nIn order to obtain a valid score for an ACH transaction, Plaid must have an access token for the account, and the Item must be healthy (receiving product updates) or have recently been in a healthy state. If the transaction does not meet eligibility requirements, an error will be returned corresponding to the underlying cause. If `/processor/signal/evaluate` is called on the same transaction multiple times within a 24-hour period, cached results may be returned. For more information please refer to our error documentation on [item errors](/docs/errors/item/) and [Link in Update Mode](/docs/link/update-mode/).\n\nNote: This request may take some time to complete if Signal is being added to an existing Item. This is because Plaid must communicate directly with the institution when retrieving the data for the first time.',
  externalDocs: { url: '/api/processors/#processorsignalevaluate' },
  operationId: 'processorSignalEvaluate',
  request: {
    body: {
      content: { 'application/json': { schema: ProcessorSignalEvaluateRequestSchema } },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: ProcessorSignalEvaluateResponseSchema,
          examples: {
            'example-1': {
              value: {
                core_attributes: {
                  days_since_first_plaid_connection: 510,
                  is_savings_or_money_market_account: false,
                  plaid_connections_count_30d: 7,
                  plaid_connections_count_7d: 6,
                  total_plaid_connections_count: 15,
                },
                request_id: 'mdqfuVxeoza6mhu',
                scores: {
                  bank_initiated_return_risk: { risk_tier: 7, score: 72 },
                  customer_initiated_return_risk: { risk_tier: 1, score: 9 },
                },
              },
            },
          },
        },
      },
    },
    default: {
      description: 'Error response.',
      content: { 'application/json': { schema: PlaidErrorSchema } },
    },
  },
})

